// ── Конфігурація ролей ────────────────────────────────────
/**
 * Єдине місце управління доступом.
 *
 * Щоб додати нову роль:
 *  1. Додай об'єкт до ROLES_CONFIG нижче
 *  2. Вкажи home — куди потрапляє після логіну
 *  3. Вкажи access — масив route name-ів (з router.js), або '*' для повного доступу
 *  4. Більше нічого не потрібно — роутер і меню підхоплять автоматично
 *
 * Route names для довідки:
 *   'main'        → /
 *   'budget'      → /budget        (тільки developer)
 *   'results'     → /results       (тільки developer)
 *   'stadnik'     → /stadnik
 *   'dudina'      → /dudina
 *   'ambrosov'    → /ambrosov
 *   'artutjan'    → /artutjan
 *   'mjaskovskiy' → /mjaskovskiy
 */
export const ROLES_CONFIG = {
    analyst: {
        home: '/',
        access: '*', // повний доступ до всіх сторінок
    },
    ceo: {
        home: '/',
        access: ['main', 'stadnik', 'dudina', 'ambrosov', 'artutjan', 'mjaskovskiy', 'budget', 'results'],
    },
    super: {
        home: '/',
        access: ['main', 'stadnik', 'dudina', 'ambrosov', 'artutjan', 'mjaskovskiy'],
    },
}

// Менеджерські ролі — генеруються автоматично з масиву MANAGERS.
// Кожен менеджер отримує доступ тільки до своєї сторінки.
// Якщо потрібно розширити доступ — перевизнач роль вручну вище.
MANAGERS.forEach(m => {
    if (!ROLES_CONFIG[m.role]) {
        ROLES_CONFIG[m.role] = {
            home: m.route,
            access: [m.id],
        }
    }
})

// ── Похідні дані (генеруються з ROLES_CONFIG) ─────────────

/** Список ролей всіх менеджерів (для зворотної сумісності) */
export const MANAGER_ROLES = MANAGERS.map(m => m.role)

/** Усі дозволені ролі */
export const ALLOWED_ROLES = Object.keys(ROLES_CONFIG)

/** Домашній маршрут для кожної ролі */
export const ROLE_HOME = Object.fromEntries(
    Object.entries(ROLES_CONFIG).map(([role, cfg]) => [role, cfg.home])
)

/**
 * Перевірити чи має роль доступ до сторінки за її route name
 * @param {string} role      — роль користувача ('super', 'stadnik', …)
 * @param {string} routeName — name маршруту з router.js ('main', 'budget', …)
 * @returns {boolean}
 */
export function hasAccess(role, routeName) {
    const cfg = ROLES_CONFIG[role]
    if (!cfg) return false
    if (cfg.access === '*') return true
    return Array.isArray(cfg.access) && cfg.access.includes(routeName)
}

// ── Вспомогательные функции ───────────────────────────────

/** Найти менеджера по id */
export function getManagerById(id) {
    return MANAGERS.find(m => m.id === id)
}

/** Найти менеджера по роли */
export function getManagerByRole(role) {
    return MANAGERS.find(m => m.role === role)
}

/** Получить цвет по имени ('Стадник' → '#6366f1') */
export function getManagerColor(name) {
    const manager = MANAGERS.find(m => m.name === name)
    return manager ? manager.color : '#94a3b8'
}

/** Получить цвет по роли ('stadnik' → '#6366f1') */
export function getColorByRole(role) {
    if (role === 'super') return 'green'
    if (role === 'promo') return 'dodgerblue'
    const manager = MANAGERS.find(m => m.role === role)
    return manager ? manager.color : 'gray'
}
