import {createRouter, createWebHashHistory} from 'vue-router'
import {MANAGERS, ROLE_HOME, ALLOWED_ROLES, hasAccess, CONFIG_VERSION} from '@/config/managers.config'

const routes = [
    // ── Публичные ─────────────────────────────────────────
    {
        path: '/login',
        name: 'login',
        component: () => import('./pages/LoginComponent.vue'),
        meta: {guestOnly: true},
    },

    // ── Главная ───────────────────────────────────────────
    {
        path: '/',
        name: 'main',
        component: () => import('./pages/MainDataComponent.vue'),
        meta: {requiresAuth: true},
    },

    // ── Страницы менеджеров — берутся из конфига ──────────
    ...MANAGERS.map(m => ({
        path: m.route,
        name: m.id,
        component: m.component,
        meta: {requiresAuth: true},
    })),

    // ── Бюджет ────────────────────────────────────────────
    {
        path: '/budget',
        name: 'budget',
        component: () => import('./pages/BudgetPage.vue'),
        meta: {requiresAuth: true},
    },

    // ── Итоги ─────────────────────────────────────────────
    {
        path: '/results',
        name: 'results',
        component: () => import('./pages/ResultsPage.vue'),
        meta: {requiresAuth: true},
    },

    // ── 404 ───────────────────────────────────────────────
    {
        path: '/:pathMatch(.*)*',
        name: 'error',
        component: () => import('./pages/ErrorComponent.vue'),
        meta: {requiresAuth: true},
    },
]

const router = createRouter({
    history: createWebHashHistory(),
    routes,
})

// ── Guard ─────────────────────────────────────────────────
router.beforeEach((to, from, next) => {
    let authData = null
    try {
        const raw = localStorage.getItem('sale-auth')
        authData = raw ? JSON.parse(raw) : null
    } catch {
        localStorage.removeItem('sale-auth')
    }

    const role = authData?.role
        ? String(authData.role).trim().toLowerCase()
        : null

    // Если версия конфига изменилась — роль пользователя могла смениться в Google Sheets.
    // Единственный способ получить актуальную роль — перелогиниться.
    // Чистим sale-auth и отправляем на логин.
    if (authData && authData.configVersion !== CONFIG_VERSION) {
        localStorage.removeItem('sale-auth')
        next('/login')
        return
    }

    // Не авторизован → на логин
    if (to.meta.requiresAuth && !authData) {
        next('/login')
        return
    }

    // Роль не существует в конфиге → на логин
    if (authData && !ALLOWED_ROLES.includes(role)) {
        next('/login')
        return
    }

    // Нет доступа к странице (кроме error — она доступна всем авторизованным)
    if (to.meta.requiresAuth && authData && to.name !== 'error') {
        if (!hasAccess(role, to.name)) {
            next(ROLE_HOME[role] || '/')
            return
        }
    }

    // Гость пытается попасть на закрытую страницу
    if (to.meta.guestOnly && authData) {
        next(ROLE_HOME[role] || '/')
        return
    }

    next()
})

export default router