import {MANAGERS} from '@/config/managers.config'

/**
 * Хранилище данных — генерируется динамически из конфига менеджеров.
 * Чтобы добавить нового менеджера — достаточно добавить его в managers.config.js
 */
export const dataStore = {
  // ── Данные компании ───────────────────────────────────
  companyData: null,
  _loadedAt:   null,         // timestamp последней загрузки

  setCompanyData(data) {
    this.companyData = data
    this._loadedAt   = Date.now()
  },

  getCompanyData() {
    return this.companyData
  },

  /**
   * Данные устарели если прошло больше maxAgeHours часов
   * @param {number} maxAgeHours — по умолчанию 8 часов
   */
  isStale(maxAgeHours = 8) {
    if (!this._loadedAt) return true
    return (Date.now() - this._loadedAt) > maxAgeHours * 3_600_000
  },

  // ── Данные менеджеров (генерируются из конфига) ───────
  _managersData: Object.fromEntries(MANAGERS.map(m => [m.id, null])),

  /**
   * Сохранить данные менеджера
   * @param {string} id   — id менеджера из конфига
   * @param {Array}  data — массив данных
   */
  setManagerData(id, data) {
    if (!(id in this._managersData)) {
      console.warn(`dataStore: менеджер "${id}" не найден в конфиге`)
      return
    }
    this._managersData[id] = data
  },

  /**
   * Получить данные менеджера
   * @param {string} id — id менеджера из конфига
   * @returns {Array|null}
   */
  getManagerData(id) {
    return this._managersData[id] ?? null
  },

  /**
   * Проверить — загружены ли данные всех менеджеров
   * @returns {boolean}
   */
  isAllLoaded() {
    return Object.values(this._managersData).every(d => d !== null)
  },

  /**
   * Сбросить все данные (например при выходе из аккаунта)
   */
  reset() {
    this.companyData = null
    this._loadedAt   = null
    MANAGERS.forEach(m => { this._managersData[m.id] = null })
  },
}
